const body = $input.first().json.body;
// Attempt to parse if body is a string
let data;
try {
  data = typeof body === 'string' ? JSON.parse(body) : body;
} catch (error) {
  console.error("Error parsing webhook body:", error);
  // Return an error structure that can be handled by a Respond node
  return { json: { error: true, message: "Invalid JSON payload in webhook body." }, status: 400 };
}

const errors = [];
if (!data.order_id) errors.push("Missing order_id");
if (!data.billing) errors.push("Missing billing information");
if (data.billing && !data.billing.phone) errors.push("Missing billing.phone");
if (data.billing && !data.billing.email) errors.push("Missing billing.email");
// First name and last name are good to have for personalization but might not be strictly essential for OTP
// if (!data.billing.first_name) errors.push("Missing billing.first_name");
// if (!data.billing.last_name) errors.push("Missing billing.last_name");

if (errors.length > 0) {
  console.error("Input validation failed:", errors.join(', '));
  return { json: { error: true, message: "Input validation failed: " + errors.join(', '), details: errors }, status: 400 };
}

return { json: data }; // Pass validated data to the next node

// Generate a 6-digit OTP
const otp = Math.floor(100000 + Math.random() * 900000);

// Access the first input item (validated data from previous node)
const data = $input.first().json;

// Safely extract billing and shipping information
const billing = data.billing || {}; // Already validated that billing exists
const shipping = data.shipping || {};

// Construct the formatted address
const addressParts = [
  shipping.address_1,
  shipping.city,
  shipping.state,
  shipping.postcode
].filter(part => part && typeof part === 'string' && part.trim() !== '').join(', ');

// Customer name: handle if one part is missing
let customerName = '';
if (billing.first_name && billing.last_name) {
  customerName = `${billing.first_name} ${billing.last_name}`.trim();
} else if (billing.first_name) {
  customerName = billing.first_name.trim();
} else if (billing.last_name) {
  customerName = billing.last_name.trim();
} else {
  customerName = 'Valued Customer'; // Fallback name
}

// Phone number cleaning: ensure it's a string before replace
const rawPhone = billing.phone || '';
const cleanedPhone = rawPhone.toString().replace(/\D/g, ''); // Remove non-digits
// Specific logic for Indian numbers: remove leading 0 or 91 if it's a full 10-digit number after that
// This regex might need adjustment based on actual phone number formats received.
// For now, assuming we want to strip country code if present for local delivery systems.
const finalPhone = cleanedPhone.length > 10 && (cleanedPhone.startsWith('91') || cleanedPhone.startsWith('0')) ? cleanedPhone.replace(/^0+|^91+/, '') : cleanedPhone;


// Format data for the next node
return {
  json: {
    orderId: data.order_id,
    customerName: customerName,
    phone: finalPhone,
    email: billing.email,
    otp: otp.toString(),
    status: data.status || 'Out for Delivery',
    timestamp: new Date().toLocaleDateString('en-IN', { timeZone: 'Asia/Kolkata' }),
    address: addressParts,
    // items: data.items || [] // Consider if items are needed for SMS or Sheets
  }
};

console.error("Failed to send SMS or bad response from MSG91:", JSON.stringify($input.first().json));
// You could add more sophisticated error handling here, like sending a notification
// For now, just log it and pass data to Google Sheets for recording failure
const previousData = $('Generate OTP & Prepare Data').first().json;
return {
    json: {
        ...previousData,
        smsSentStatus: 'Failed: ' + ($input.first().json.body.message || JSON.stringify($input.first().json.body))
    }
};

console.error("Failed to upsert to Google Sheets:", JSON.stringify($input.first().json));
// Final error logging or notification node
return { json: { error: true, message: "Failed to update Google Sheets", details: $input.first().json } };
